/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-switch> - a mechanical switch, and the talkback flag that answers it.
 *
 * Four kinds, each drawn
 * face-on as it sits in a panel:
 *
 *   toggle  a rod on a bushing, two or three positions (the default)
 *   flick   a momentary toggle that springs back to rest
 *   lever   a vertical lever in a slot, with a detent per position
 *   rocker  two halves with the positions printed on them, such as I and O
 *
 * A toggle or flick rod is `look="rounded"` (the default) or `look="triangle"`,
 * a flat blade. Any kind can carry a GUARD, lifted by an `ov-hold`.
 *
 *   <ov-switch positions="REL,OFF,LAT" set="OFF" transit="8"
 *              guard="IRREVERSIBLE" label="MRL"></ov-switch>
 *   sw.addEventListener('ov:command', (e) => plant.drive(e.detail.to));
 *   plant.onSensor = (word) => { sw.talkback = word; };  // null: between positions
 *
 *   // or a whole state at once, its time stated as seconds before now:
 *   sw.reading = { set: 'LAT', talkback: null, commandedAgo: 3 };
 *
 *   <ov-switch kind="rocker" positions="I,O" lamp="I" label="PUMP"></ov-switch>
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 THE POSITION YOU SET IS NOT THE STATE THE SYSTEM CONFIRMED. The handle
 * shows what the operator did. The flag above it shows what the position
 * sensors report, and NOTHING ELSE writes to it: not the handle, not the
 * command, not a timer. Until a sensor reports a position the flag is
 * BARBERPOLE, which is neither position.
 *
 * STS News Reference Manual (NASA, 1988), C&W section: "The talkback indicator
 * above the release, off, latch switch on panel A8L indicates barberpole when
 * the MRLs are in transit and rel when they are released." "If a talkback
 * indicator shows barberpole, the MRL is not correctly aligned or not in
 * position to be able to latch down the arm."
 *
 * And five that follow from it:
 *
 * 1. AFTER A COMMAND THE RESULT IS SUCCESS, FAIL OR UNKNOWN, NEVER ASSUMED.
 *    NASA-STD-3001 Vol 2 Rev F, App. F.4.3.2: "Commands that change vehicle
 *    state must provide a positive indication of control activation (e.g.,
 *    telemetry change, message indicating completed, running, failed, or
 *    unknown)." So a command is IN TRANSIT for its declared `transit`, and
 *    past that with no position reported it is UNKNOWN; with the old position
 *    still reported it is FAIL.
 *    ⚠️ INFERRED, NOT STATED: that an overrun of the declared transit is where
 *    "in transit" becomes "unknown". The manual gives the RMS latch times
 *    (about 8 s on two motors, about 18 s on one) and no rule about overruns.
 *    A late arrival still confirms the command.
 * 2. A CONFIRMED POSITION THAT CHANGES WITH NO COMMAND IS UNCOMMANDED, and one
 *    that leaves its position is NOT IN POSITION. The sensor moved; the
 *    handle did not; the display does not pick the handle. A reading cannot
 *    carry that history, so it states it (`confirmed`) rather than having it
 *    guessed from two words that differ, which on their own read DISAGREE.
 * 3. A GUARDED SWITCH NEEDS TWO INDEPENDENT ACTIONS, AND ARMED IS ITSELF SHOWN.
 *    F.4.3.2: "The system must require at least 2 independent commands to
 *    activate/execute mission critical and safety critical controls."
 *    "Commands with an arm control must be accompanied by a safe control
 *    (that removes the armed condition) located to the right or beneath the
 *    arm control." HIDH 10.4.6 names "switch guards, covers" among the
 *    protective measures. The arm is an `ov-hold`, so lifting the guard is
 *    itself deliberate and has its price on it; SAFE sits to its right.
 * 4. A FLICK SWITCH SPRINGS BACK, so its handle is drawn at rest whatever was
 *    commanded, and the last command is written out because that line is the
 *    only copy of it. On a flick switch the talkback is the only thing that
 *    can show the position, which is the refusal at its plainest.
 * 5. A LAMP LIGHTS ON THE TALKBACK, NEVER ON THE SWITCH. `lamp` names the
 *    position that lights a rocker, and it is lit only while the talkback
 *    confirms that position. A lit rocker wired to its own contacts is the
 *    lie this element refuses, drawn in light.
 *
 * Not `ov-hold` plus one `ov-procedure` row: neither has a state that is
 * NEITHER position, and barberpole is that state.
 *
 * No animation frames. One timer per command, started through whenArrived(),
 * which re-evaluates once when the declared transit has run out.
 */

import { define, whenArrived } from '../../../src/ov-core.js';
import '../../../src/ov-hold.js';

const KINDS = new Set(['toggle', 'flick', 'lever', 'rocker']);
const LOOKS = new Set(['rounded', 'triangle']);

const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

export class OvSwitch extends HTMLElement {
  static observedAttributes = ['positions', 'kind', 'look', 'guard', 'transit', 'lamp', 'label', 'src', 'source'];

  constructor() {
    super();
    this._set = null;
    // undefined: nothing has ever reported. null: reported, between positions.
    this._talkback = undefined;
    this._commandedAt = null;
    this._reached = false;
    this._armed = false;

    this.addEventListener('click', (e) => {
      const b = e.target.closest('.ov-switch__pos, .ov-switch__safe');
      if (!b || b.closest('ov-switch') !== this) return;
      if (b.classList.contains('ov-switch__safe')) this.safe();
      else this.command(b.dataset.ovPos);
    });
    // The guard lifts only on a completed hold, never on a press.
    this.addEventListener('ov:commit', (e) => {
      if (e.target.classList?.contains('ov-switch__armhold') && e.target.closest('ov-switch') === this) this.arm();
    });
  }

  connectedCallback() {
    if (!this._built) {
      // `set` is where the handle was left, declared once. It is not a
      // command and it confirms nothing.
      this._set = this.declared();
      this.build();
    }
    this.fetchSrc();
    this.bindSource();
    this.evaluate();
  }

  disconnectedCallback() {
    clearTimeout(this._timer);
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    if (name === 'positions' || name === 'kind' || name === 'look' || name === 'guard') this.build();
    if (name === 'transit') this.schedule();
    this.evaluate();
  }

  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch { data = null; }
    if (this.getAttribute('src') !== src) return;
    this.reading = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    // A feed may send a whole reading, or only the talkback's word.
    this.unsub = window.Overscan.subscribe(name, (x) => {
      if (x && typeof x === 'object') this.reading = x; else this.talkback = x;
    });
  }

  positions() {
    const p = (this.getAttribute('positions') || 'OFF,ON').split(',').map((x) => x.trim()).filter(Boolean);
    return p.length >= 2 ? p : ['OFF', 'ON'];
  }

  kind() { const k = this.getAttribute('kind'); return KINDS.has(k) ? k : 'toggle'; }
  look() { const l = this.getAttribute('look'); return LOOKS.has(l) ? l : 'rounded'; }
  guarded() { return this.hasAttribute('guard'); }
  transitMs() { const t = Number(this.getAttribute('transit') ?? 8); return (Number.isFinite(t) && t >= 0 ? t : 8) * 1000; }
  // Where a flick switch springs back to: the centre of three, the first of two.
  rest() { const p = this.positions(); return p[(p.length - 1) >> 1]; }
  label() { return this.getAttribute('label') || 'SWITCH'; }
  declared() { const s = this.getAttribute('set'); return s !== null && this.positions().includes(s) ? s : null; }

  get set() { return this._set; }
  get armed() { return this._armed; }
  get talkback() { return this._talkback; }

  /* The position the sensors report: a position word, or null between
   * positions. The only writer of the flag. */
  set talkback(v) {
    this._talkback = typeof v === 'string' ? v : v === undefined ? undefined : null;
    if (this._set !== null && this._talkback === this._set) this._reached = true;
    this.evaluate();
  }

  /* A whole state at once, for a feed or a stored scene:
   *   { set, talkback, commandedAgo, armed, confirmed }
   * A missing `talkback` key is NO TALKBACK, not a position. `commandedAgo` is
   * seconds before now, so a scene written today does not read as old later.
   * `armed` is ignored on a switch with no guard. */
  set reading(r) {
    if (!r || typeof r !== 'object') {
      this._set = this.declared();
      this._talkback = undefined;
      this._commandedAt = null;
      this._reached = false;
      this.schedule();
      this.evaluate();
      return;
    }
    const pos = this.positions();
    const ago = Number(r.commandedAgo);
    this._set = pos.includes(r.set) ? r.set : null;
    this._commandedAt = r.commandedAgo !== undefined && r.commandedAgo !== null && Number.isFinite(ago) && ago >= 0 ? Date.now() - ago * 1000 : null;
    if (this.guarded()) this._armed = !!r.armed;
    this._talkback = !Object.hasOwn(r, 'talkback') ? undefined : typeof r.talkback === 'string' ? r.talkback : null;
    this._reached = this._set !== null && this._talkback === this._set ? true : !!r.confirmed;
    this.schedule();
    this.evaluate();
  }

  get reading() {
    return {
      set: this._set,
      talkback: this._talkback,
      commandedAgo: this._commandedAt === null ? null : (Date.now() - this._commandedAt) / 1000,
      armed: this._armed,
      confirmed: this._reached,
    };
  }

  command(to) {
    if (!this.positions().includes(to)) return false;
    // Refusal 3: the guard first, then the switch. Two actions, not one.
    if (this.guarded() && !this._armed) return false;
    const from = this._set;
    this._set = to;
    this._commandedAt = Date.now();
    this._reached = this._talkback === to;
    this.schedule();
    this.dispatchEvent(new CustomEvent('ov:command', { detail: { from, to }, bubbles: true }));
    this.evaluate();
    return true;
  }

  /* One timer, for the moment the declared transit runs out. */
  schedule() {
    clearTimeout(this._timer);
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._commandedAt === null || this._commandedAt + this.transitMs() < Date.now()) return;
    this._unarrive = whenArrived(() => {
      const left = this._commandedAt === null ? 0 : this._commandedAt + this.transitMs() - Date.now();
      this._timer = setTimeout(() => this.evaluate(), Math.max(0, left) + 20);
    });
  }

  arm() {
    if (!this.guarded()) return;
    this._armed = true;
    this.evaluate();
    this.dispatchEvent(new CustomEvent('ov:arm', { bubbles: true }));
  }

  safe() { this._armed = false;
    this.evaluate();
    this.dispatchEvent(new CustomEvent('ov:safe', { bubbles: true }));
  }

  evaluate() {
    if (!this._built) return this._report;
    const pos = this.positions();
    const tb = this._talkback;
    const secs = this.transitMs() / 1000;
    const r = { state: 'unknown', word: '', why: '', set: this._set, talkback: tb, armed: this._armed, handle: null };
    // Refusal 4: a flick switch springs back, whatever was commanded.
    r.handle = this.kind() === 'flick' ? this.rest() : r.set;
    const commanded = this._commandedAt !== null;
    const inWindow = this._commandedAt !== null && Date.now() - this._commandedAt < this.transitMs();
    const agrees = tb === r.set;

    if (typeof tb === 'string' && !pos.includes(tb)) {
      r.word = 'UNKNOWN';
      r.why = `TALKBACK READS ${tb}, WHICH IS NOT A POSITION OF THIS SWITCH`;
    } else if (tb === undefined) {
      r.word = 'NO TALKBACK';
      r.why = `${r.set === null ? '' : `SET ${r.set} · `}NOTHING HAS REPORTED A POSITION`;
    } else if (r.set === null) {
      r.state = tb === null ? 'unknown' : 'reading';
      r.word = tb === null ? 'NOT IN POSITION' : '';
    } else if (agrees) {
      r.state = 'agree';
    } else if (inWindow) {
      r.state = 'transit';
      r.word = 'IN TRANSIT';
      r.why = `COMMANDED ${r.set} · ALLOWED ${secs} S`;
    } else if (tb === null) {
      r.word = this._reached ? 'NOT IN POSITION' : 'UNKNOWN';
      r.why = this._reached ? `SET ${r.set} · LEFT ITS POSITION WITH NO COMMAND`
        : commanded ? `COMMANDED ${r.set} · NO POSITION REPORTED WITHIN ${secs} S`
          : `SET ${r.set} · NO POSITION REPORTED`;
    } else {
      // Refusal 2: the sensor moved and the handle did not. Neither is picked.
      r.state = this._reached ? 'uncommanded' : commanded ? 'fail' : 'disagree';
      r.word = r.state.toUpperCase();
      r.why = `${commanded && !this._reached ? 'COMMANDED' : 'SET'} ${r.set} · TALKBACK READS ${tb}`;
    }

    const tone = r.state === 'agree' || r.state === 'reading' ? 'ok' : r.state === 'transit' ? 'note' : 'bad';
    const shown = typeof tb === 'string' && pos.includes(tb) ? tb : r.set;  // MUTANT
    this._report = r;
    this.paint(r, tone, shown, secs);
    return r;
  }

  get report() { return this._report; }

  /* ---- drawing ---------------------------------------------------------- */

  build() {
    this._built = true;
    const pos = this.positions();
    const guard = this.guarded();
    const kind = this.kind();
    this.setAttribute('role', 'group');
    setAttr(this, 'data-ov-kind', kind);
    // A look shapes a rod, so only the kinds that have one take it.
    setAttr(this, 'data-ov-look', kind === 'toggle' || kind === 'flick' ? this.look() : null);
    const hold = this.getAttribute('arm-hold');
    this.innerHTML = `
      <div class="ov-head">
        <span class="ov-aside ov-head__name ov-switch__label"></span>
        <span class="ov-aside ov-head__note ov-switch__rule"></span>
      </div>
      <div class="ov-switch__flag" aria-hidden="true"></div>
      <div class="ov-switch__plate" role="radiogroup" style="--ov-sw-n:${pos.length}">
        <span class="ov-switch__mech" aria-hidden="true"><i class="ov-switch__pivot"></i><i class="ov-switch__bat"></i><i class="ov-switch__tip"></i></span>
        ${pos.map((p) => `<button type="button" class="ov-switch__pos" role="radio" data-ov-pos="${esc(p)}">${esc(p)}</button>`).join('')}
        ${guard ? '<span class="ov-switch__guard" aria-hidden="true"><span class="ov-switch__guardword">GUARD</span></span>' : ''}
      </div>
      <div class="ov-switch__cmd"></div>
      ${guard ? `<div class="ov-switch__arm">`
        + `<ov-hold class="ov-switch__armhold" label="ARM" price="${esc(this.getAttribute('guard') || 'GUARDED')}"${hold ? ` hold="${esc(hold)}"` : ''}></ov-hold>`
        + `<button type="button" class="ov-btn ov-switch__safe">SAFE</button>`
        + `<span class="ov-switch__armed">ARMED</span></div>` : ''}
      <div class="ov-state ov-state--bar ov-switch__out">
        <span class="ov-state__word ov-switch__word"></span>
        <span class="ov-aside ov-switch__why"></span>
      </div>`;
  }

  paint(r, tone, shown, secs) {
    const q = (s) => this.querySelector(s);
    const pos = this.positions();
    const locked = this.guarded() && !this._armed;
    const lamp = this.getAttribute('lamp');

    setText(q('.ov-switch__label'), this.label());
    setText(q('.ov-switch__rule'), `${pos.join(' / ')} · TRANSIT ${secs} S${this.guarded() ? ' · GUARDED' : ''}`);
    setAttr(q('.ov-switch__plate'), 'aria-label', this.label());

    setAttr(this, 'data-ov-state', r.state);
    setAttr(this, 'data-ov-refusal', tone === 'bad' ? 'unknown' : null);
    setAttr(this, 'data-ov-qualified', r.state === 'transit' ? 'unchecked' : null);
    setAttr(this, 'data-ov-armed', this._armed ? '' : null);
    // Refusal 5: the lamp answers the talkback, not the rocker.
    setAttr(this, 'data-ov-lit', r.state === 'agree' && lamp !== null && r.set === lamp ? '' : null);

    // 🔴 The flag: the sensor's word, or barberpole. Never the handle's.
    const flag = q('.ov-switch__flag');
    setAttr(flag, 'data-ov-flag', shown === null ? 'barberpole' : 'word');
    setText(flag, shown === null ? '' : shown);

    const n = pos.length;
    const i = pos.indexOf(r.handle);
    const y = i < 0 ? 50 : ((i + 0.5) / n) * 100;
    const plate = q('.ov-switch__plate');
    plate.style.setProperty('--ov-sw-y', `${y}%`);
    setAttr(this, 'data-ov-handle', r.handle === null ? '' : r.handle);
    // Which way the rod leans, so it can be drawn in perspective: wide at the
    // tip, which is nearer the reader, and end-on at a centre position.
    setAttr(this, 'data-ov-lean', i < 0 ? null : y < 50 ? 'up' : y > 50 ? 'down' : 'mid');

    for (const b of this.querySelectorAll('.ov-switch__pos')) {
      const w = b.dataset.ovPos;
      setAttr(b, 'aria-checked', String(w === r.set));
      setAttr(b, 'data-ov-set', w === r.set && this.kind() !== 'flick' ? '' : null);
      b.disabled = locked;
    }
    setText(q('.ov-switch__cmd'), this.kind() === 'flick' && r.set !== null ? `LAST COMMAND ${r.set}` : '');

    const out = q('.ov-switch__out');
    setAttr(out, 'data-ov-tone', tone);
    setText(q('.ov-switch__word'), r.word);
    setText(q('.ov-switch__why'), r.why);

    this.setAttribute('aria-label', `${this.label()}: set ${r.set ?? 'nowhere'}, talkback ${shown ?? 'barberpole'}`
      + `${r.word ? `, ${r.word.toLowerCase()}` : ''}${this.hasAttribute('data-ov-lit') ? ', lamp lit' : ''}`
      + `${this.guarded() ? (this._armed ? ', armed' : ', guarded') : ''}`);
  }
}

define('ov-switch', OvSwitch);
